class InheritedGraphContextRenderTest {

	@Test
	void renderingRestoresCallerGraphAndKeepsSameNamedLocalGraph() throws Exception {
		for (int renderer = 0; renderer < 3; renderer++) {
			for (boolean prepared : new boolean[] { false, true }) {
				for (boolean nested : new boolean[] { false, true }) {
					for (boolean paths : new boolean[] { false, true }) {
						assertRoundTrip(renderer, prepared, nested, paths);
					}
				}
			}
		}
	}

	private void assertRoundTrip(int renderer, boolean prepared, boolean nested, boolean paths) throws Exception {
		String pattern = paths ? "?x <urn:p>+ ?endpoint FILTER(?endpoint = <urn:o>)" : "?x <urn:p> <urn:o>";
		String inherited = nested ? "{ SELECT ?x { " + pattern + " } }" : pattern;
		String local = paths ? "?y <urn:p>+ ?localEndpoint FILTER(?localEndpoint = <urn:o>)"
				: "?y <urn:p> <urn:o>";
		TupleExpr expression = parse("SELECT ?g ?x ?y { GRAPH ?g { ?seed <urn:p> <urn:o> OPTIONAL { "
				+ "SELECT ?x ?y { " + inherited + " GRAPH ?g { " + local + " } } } } }");
		List<String> expected = List.of("{g=urn:g1, x=urn:a, y=urn:a}", "{g=urn:g1, x=urn:a, y=urn:b}",
				"{g=urn:g2, x=urn:b, y=urn:a}", "{g=urn:g2, x=urn:b, y=urn:b}");
		if (prepared) {
			assertThat(evaluate(expression)).containsExactlyElementsOf(expected);
			assertThat(expression.toString()).contains("_rdf4j_graph_context_");
		}
		String rendered = switch (renderer) {
		case 0 -> new TupleExprIRRenderer().render(expression);
		case 1 -> new SPARQLQueryRenderer().render(new ParsedTupleQuery(expression));
		case 2 -> new SparqlQueryRenderer().render(new ParsedTupleQuery(expression));
		default -> throw new AssertionError("Unknown renderer");
		};
		assertThat(rendered).doesNotContain("_rdf4j_graph_context_");
		assertThat(evaluate(parse(rendered))).as(rendered).containsExactlyElementsOf(expected);
	}

	private TupleExpr parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private List<String> evaluate(TupleExpr expression) {
		ValueFactory vf = SimpleValueFactory.getInstance();
		List<Statement> data = List.of(
				vf.createStatement(vf.createIRI("urn:a"), vf.createIRI("urn:p"), vf.createIRI("urn:o"),
						vf.createIRI("urn:g1")),
				vf.createStatement(vf.createIRI("urn:b"), vf.createIRI("urn:p"), vf.createIRI("urn:o"),
						vf.createIRI("urn:g2")));
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(data.stream()
						.filter(row -> subject == null || subject.equals(row.getSubject()))
						.filter(row -> predicate == null || predicate.equals(row.getPredicate()))
						.filter(row -> object == null || object.equals(row.getObject()))
						.filter(row -> contexts.length == 0 || Arrays.asList(contexts).contains(row.getContext()))
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return vf;
			}
		};
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = new DefaultEvaluationStrategy(source, null)
				.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				BindingSet bindings = iteration.next();
				Map<String, String> row = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					row.put(name, bindings.getValue(name).toString());
				}
				rows.add(row.toString());
			}
		}
		rows.sort(null);
		return rows;
	}
}
